package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Person struct {
	Name string
	Age  int
}

func (p Person) Introduce() string {
	return fmt.Sprintf("私は%s、%d歳です", p.Name, p.Age)
}

// Person を埋め込んだ Employee です
type Employee struct {
	Person
	Company string
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	fields := strings.Fields(sc.Text())
	name := fields[0]
	age, _ := strconv.Atoi(fields[1])
	sc.Scan()
	company := sc.Text()

	// ここから下を書く: Employee を作り、
	// 1 行目: 昇格した Introduce() の結果
	// 2 行目: 勤務先は<会社名>です
	_ = name
	_ = age
	_ = company
}

